window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-109"]=[{"id":"set2-mBqOzu-p","fingerprint":"1717b3a8f5bcdf1f","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care sunt cele patru tipuri de țesuturi care constituie parodonțiul?","options":[{"id":"A","text":"Gingia, ligamentul parodontal, cementul radicular și osul alveolar."},{"id":"B","text":"Ligamentul parodontal, gingia, osul alveolar și lamina propria."},{"id":"C","text":"Ligamentul parodontal, cementul radicular, dentina și lamina propria."},{"id":"D","text":"Gingia liberă, gingia atașată, gingia interdentară și osul maxilar."},{"id":"E","text":"Gingia, osul alveolar, smalțul dentar și epiteliul joncțional."}],"correct":["A"],"pages":[291],"source":"set-2"},{"id":"set2-rkWZBkzC","fingerprint":"01f8a4868f9f4a11","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care dintre următoarele structuri formează parodonțiul profund?","options":[{"id":"A","text":"Ligamentul parodontal, cementul radicular și osul alveolar."},{"id":"B","text":"Gingia, ligamentul parodontal, cementul radicular și osul alveolar."},{"id":"C","text":"Doar ligamentul parodontal și osul alveolar."},{"id":"D","text":"Cementul radicular, osul alveolar și gingia."},{"id":"E","text":"Gingia și ligamentul parodontal."}],"correct":["A"],"pages":[291],"source":"set-2"},{"id":"set2-kjFVwQo6","fingerprint":"a79bf1292405e553","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care sunt cele trei zone anatomice în care este împărțită gingia?","options":[{"id":"A","text":"Gingia marginală, gingia atașată și gingia interdentară."},{"id":"B","text":"Gingia marginală, șanțul gingival și zenitul gingival."},{"id":"C","text":"Gingia superficială, gingia profundă și papilele interdentare."},{"id":"D","text":"Gingia coronară, gingia apicală și gingia inter-radiculară."},{"id":"E","text":"Gingia liberă, epiteliul joncțional și lamina propria."}],"correct":["A"],"pages":[291],"source":"set-2"},{"id":"set2-hbmJWalt","fingerprint":"f806900a5de65961","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Referitor la gingia marginală (liberă), care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Reprezintă peretele extern al șanțului gingival."},{"id":"B","text":"Este separată de gingia fixă prin șanțul gingiei libere, vizibil în 100% din cazuri."},{"id":"C","text":"Are o grosime constantă de 1,5 mm."},{"id":"D","text":"Aderă la cement prin țesutul conjunctiv subepitelial propriu, numit lamina propria."},{"id":"E","text":"Aderă la smalț prin intermediul epiteliului joncțional."}],"correct":["A","D","E"],"pages":[291],"source":"set-2"},{"id":"set2-4bVfjWQH","fingerprint":"af794644b1e9fce3","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce reprezintă zenitul gingival?","options":[{"id":"A","text":"Peretele extern al șanțului gingival."},{"id":"B","text":"Lățimea standard a gingiei marginale."},{"id":"C","text":"Cel mai apical punct al gingiei libere."},{"id":"D","text":"Gingia situată între doi dinți adiacenți."},{"id":"E","text":"Șanțul care separă gingia liberă de cea fixă."}],"correct":["C"],"pages":[291],"source":"set-2"},{"id":"set2-29sYNujc","fingerprint":"d11980f73ed2e0e2","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt caracteristicile macroscopice ale gingiei marginale sănătoase?","options":[{"id":"A","text":"Contur neted și aspect regulat."},{"id":"B","text":"Profil rotunjit și consistență moale."},{"id":"C","text":"Grosime variabilă între 0,5 și 2 mm."},{"id":"D","text":"Profil ascuțit și consistență fermă."},{"id":"E","text":"Culoare roșu-intens și contur neregulat."}],"correct":["A","C","D"],"pages":[291],"source":"set-2"},{"id":"set2-kc65HQdF","fingerprint":"a6702e7c137c89c5","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care sunt limitele anatomice ale șanțului gingival?","options":[{"id":"A","text":"Suprafața dintelui și epiteliul ce căptușește gingia liberă."},{"id":"B","text":"Gingia liberă și gingia atașată."},{"id":"C","text":"Punctul de contact interdentar și creasta osoasă alveolară."},{"id":"D","text":"Epiteliul joncțional și osul alveolar subiacent."},{"id":"E","text":"Suprafața dintelui și joncțiunea muco-gingivală."}],"correct":["A"],"pages":[292],"source":"set-2"},{"id":"set2-cPLkrEx-","fingerprint":"171bd79bd243269e","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce valori caracterizează adâncimea șanțului gingival în condiții de sănătate parodontală, la determinarea pe secțiuni histologice?","options":[{"id":"A","text":"Depășește întotdeauna 3 mm."},{"id":"B","text":"Variază între 0,2 și 0,3 mm, cu o medie de 0,25 mm."},{"id":"C","text":"Variază între 0,5 și 3 mm, cu o medie de 1,8 mm."},{"id":"D","text":"Are o valoare medie de 3 mm."},{"id":"E","text":"Este constantă, având valoarea de 0,5 mm."}],"correct":["C"],"pages":[292],"source":"set-2"},{"id":"set2-NpdmBnIA","fingerprint":"7e9a1d2d952382f0","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care dintre următoarele afirmații despre gingia atașată sunt adevărate?","options":[{"id":"A","text":"Este mai bine reprezentată în segmentele posterioare decât în zona incisivă."},{"id":"B","text":"Aderă ferm de periostul osului alveolar subiacent."},{"id":"C","text":"Modificările de înălțime se datorează deplasării joncțiunii muco-gingivale."},{"id":"D","text":"Este separată de mucoasa alveolară prin proiecția bazei șanțului gingival."},{"id":"E","text":"Înălțimea sa este mai mare la mandibulă decât la maxilar."}],"correct":["B"],"pages":[292],"source":"set-2"},{"id":"set2-T-FnZfl2","fingerprint":"046439fa529d08b4","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce diferențiază înălțimea gingiei atașate de înălțimea gingiei keratinizate?","options":[{"id":"A","text":"Gingia keratinizată include și mucoasa alveolară."},{"id":"B","text":"Nu există nicio diferență, termenii sunt sinonimi."},{"id":"C","text":"Gingia keratinizată include și gingia marginală."},{"id":"D","text":"Gingia keratinizată include și epiteliul joncțional."},{"id":"E","text":"Gingia atașată este nekeratinizată, spre deosebire de cea keratinizată."}],"correct":["C"],"pages":[292],"source":"set-2"},{"id":"set2-5D3R676s","fingerprint":"436ae7c5f9ea9644","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este forma papilei interdentare în zona laterală a arcadelor dentare, în condiții de sănătate parodontală?","options":[{"id":"A","text":"Este identică cu forma din zona frontală."},{"id":"B","text":"Are o formă concavă, ca o șa."},{"id":"C","text":"Are o formă piramidală."},{"id":"D","text":"Este aplatizată și se contopește cu gingia atașată."},{"id":"E","text":"Prezintă două creste, una vestibulară și una orală, unite printr-o depresiune numită col gingival."}],"correct":["E"],"pages":[292],"source":"set-2"},{"id":"set2-_VcyVSb4","fingerprint":"bbfaf7fef71a9416","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Pe lângă keratinocite, care reprezintă principalul tip celular, ce alte tipuri de celule se mai găsesc în epiteliul gingival?","options":[{"id":"A","text":"Melanocite"},{"id":"B","text":"Fibroblaste"},{"id":"C","text":"Celule Merkel"},{"id":"D","text":"Celule Langerhans"},{"id":"E","text":"Osteoblaste"}],"correct":["A","C","D"],"pages":[292],"source":"set-2"},{"id":"set2-udBDCFjj","fingerprint":"3e96272de4f8bb10","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care este localizarea și întinderea epiteliului gingival extern?","options":[{"id":"A","text":"Este localizat între epiteliul sulcular și cel joncțional."},{"id":"B","text":"Se întinde de la vârful gingiei marginale până la joncțiunea muco-gingivală."},{"id":"C","text":"Acoperă suprafața exterioară a gingiei marginale și a gingiei fixe."},{"id":"D","text":"Căptușește peretele moale al șanțului gingival."},{"id":"E","text":"Se află exclusiv la nivelul papilelor interdentare."}],"correct":["B","C"],"pages":[292],"source":"set-2"},{"id":"set2-hu6Ttsx6","fingerprint":"69a6a1465b8ec605","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce strat al epiteliului gingival extern este format din 10-20 de rânduri de celule poliedrice?","options":[{"id":"A","text":"Lamina propria."},{"id":"B","text":"Stratul cornos."},{"id":"C","text":"Stratul granular."},{"id":"D","text":"Stratul spinos."},{"id":"E","text":"Stratul bazal."}],"correct":["D"],"pages":[292],"source":"set-2"},{"id":"set2-H68KJM6N","fingerprint":"518bd4785f59d2ee","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este considerat elementul de vulnerabilitate histologică a epiteliului gingival extern?","options":[{"id":"A","text":"Prezența melanocitelor, care slăbesc coeziunea celulară."},{"id":"B","text":"Traiectul ondulat al limitei cu țesutul conjunctiv."},{"id":"C","text":"Absența organitelor celulare în stratul bazal."},{"id":"D","text":"Grosimea sa de aproximativ 0,2-0,3 mm, considerată prea subțire."},{"id":"E","text":"Partea mediană a papilei interdentare, deoarece este nekeratinizată."}],"correct":["E"],"pages":[292],"source":"set-2"},{"id":"set2-YYT14EsY","fingerprint":"819cd2100852b079","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este o caracteristică fundamentală a epiteliului sulcular care îi conferă vulnerabilitate în fața agresiunilor?","options":[{"id":"A","text":"Este ferm atașat de suprafața dentară."},{"id":"B","text":"Are o grosime de 10 până la 20 de straturi celulare în zona sa apicală."},{"id":"C","text":"Acționează ca o barieră impermeabilă."},{"id":"D","text":"Este format din 10-20 de straturi celulare."},{"id":"E","text":"Este un epiteliu nekeratinizat."}],"correct":["E"],"pages":[293],"source":"set-2"},{"id":"set2-CxqA9b2i","fingerprint":"15c848b3ba68a3fa","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele reprezintă elemente de vulnerabilitate histologică ale epiteliului joncțional?","options":[{"id":"A","text":"Spațiile intercelulare largi care cresc permeabilitatea."},{"id":"B","text":"Sinteza crescută de colagen de către fibroblaste."},{"id":"C","text":"Contactul plan dintre epiteliu și lamina propria."},{"id":"D","text":"Prezența unui strat gros de keratină la suprafață."},{"id":"E","text":"Numărul redus de desmozomi comparativ cu epiteliul gingival extern."}],"correct":["A","C","E"],"pages":[293],"source":"set-2"},{"id":"set2-bfGlFS32","fingerprint":"609c4c45ad73ecb9","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce componentă reprezintă aproximativ 60% din volumul țesutului conjunctiv gingival (lamina propria)?","options":[{"id":"A","text":"Fibrele de colagen."},{"id":"B","text":"Fibroblaștii."},{"id":"C","text":"Celulele de tip limfocitar și neutrofilele."},{"id":"D","text":"Macrofagele și histiocitele."},{"id":"E","text":"Substanța fundamentală."}],"correct":["A"],"pages":[293],"source":"set-2"},{"id":"set2-BTQX9uIz","fingerprint":"e03e295ea718c348","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este descrierea corectă pentru fibrele conjunctive gingivale de tip transseptal?","options":[{"id":"A","text":"Se inseră în cementul supraalveolar, trec peste creasta alveolară și ajung în periostul corticalei externe."},{"id":"B","text":"Se inseră în cementul unui dinte și merg spre cementul dintelui adiacent în sens mezio-distal."},{"id":"C","text":"Înconjoară dintele ca un inel și sunt localizate sub epiteliul joncțional."},{"id":"D","text":"Pornesc din porțiunea supraalveolară a cementului și se proiectează în lamina propria a gingiei adiacente."},{"id":"E","text":"Se inseră în creasta alveolară, au direcție coronară și se termină în lamina propria a gingiei marginale libere."}],"correct":["B"],"pages":[293],"source":"set-2"},{"id":"set2-VtDro3Vg","fingerprint":"68f29a56c9bb6258","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce rol îndeplinesc fibroblastele pentru a asigura homeostazia locală în condiții de sănătate parodontală?","options":[{"id":"A","text":"Se diferențiază în monocite sanguine."},{"id":"B","text":"Dreanajul fluidului tisular și răspândirea inflamației."},{"id":"C","text":"Prezintă antigenii, activând răspunsul imun."},{"id":"D","text":"Formează proiecții papilare în interiorul epiteliului."},{"id":"E","text":"Sintetizează și degradează colagenul în egală măsură."}],"correct":["E"],"pages":[293],"source":"set-2"},{"id":"set2-kwRSin1I","fingerprint":"ba52a2f4e83f75e1","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Din ce structuri provin arteriolele supraperiostale care reprezintă una dintre cele trei surse sanguine ale gingiei?","options":[{"id":"A","text":"Din interiorul septului interdentar."},{"id":"B","text":"Din rețeaua limfatică a gingiei marginale libere."},{"id":"C","text":"Arteriole supraperiostale, situate pe fața vestibulară sau linguală a osului alveolar."},{"id":"D","text":"Direct din pulpa dentară prin canale accesorii."},{"id":"E","text":"Din plexul vascular al mucoasei jugale adiacente."}],"correct":["C"],"pages":[293],"source":"set-2"},{"id":"set2-MdR57JU6","fingerprint":"ce24a2702ebaaa2d","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect epiteliul joncțional într-o stare de sănătate parodontală?","options":[{"id":"A","text":"Reprezintă o bandă de epiteliu scuamos stratificat nekeratinizat."},{"id":"B","text":"Este mai gros spre sulcus, având între 10 și 20 de straturi celulare."},{"id":"C","text":"Limita sa apicală este situată la nivelul joncțiunii smalț-cement."},{"id":"D","text":"Conține aproximativ 60% fibre de colagen în structura sa."},{"id":"E","text":"Este format din două straturi distincte: unul papilar și unul reticular."}],"correct":["A","B","C"],"pages":[293],"source":"set-2"},{"id":"set2-xK_LOmhe","fingerprint":"f96b2c84499c032d","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt sursele de vascularizație sanguină ale gingiei?","options":[{"id":"A","text":"Vase provenite din ligamentul parodontal care se anastomozează cu capilarele din zona sulcusului."},{"id":"B","text":"Vase limfatice care urmează traiectul sistemului arterial."},{"id":"C","text":"Arteriole supraperiostale situate pe fața vestibulară sau linguală a osului alveolar."},{"id":"D","text":"Ramuri directe din artera facială care irigă epiteliul sulcular."},{"id":"E","text":"Arteriole care apar din creasta septului interdental."}],"correct":["A","C","E"],"pages":[294],"source":"set-2"},{"id":"set2-vCOkrnqH","fingerprint":"427ca01f3bc76418","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce caracteristică a spațiului ligamentului parodontal este corect descrisă?","options":[{"id":"A","text":"Pe radiografii, apare ca o radioopacitate care înconjoară rădăcina dintelui."},{"id":"B","text":"Este mai larg în regiunea mijlocie a rădăcinii și mai îngust la apex."},{"id":"C","text":"Este un țesut conjunctiv specializat care realizează legătura dintre smalț și osul alveolar."},{"id":"D","text":"Dimensiunea sa poate crește la nivelul dinților supuși hiperfuncției."},{"id":"E","text":"Lățimea sa medie este de aproximativ 0,2 mm, fiind mai îngustă în regiunile apicale și gingivale."}],"correct":["D"],"pages":[294],"source":"set-2"},{"id":"set2-HNvXlSk1","fingerprint":"54c9c1e2404348e3","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt afirmațiile corecte despre fibroblastele din ligamentul parodontal?","options":[{"id":"A","text":"Reglează „turnover-ul” fibrelor de colagen."},{"id":"B","text":"Sunt implicate atât în formarea, cât și în degradarea fibrelor de colagen."},{"id":"C","text":"Funcția lor principală este sinteza fibrelor de oxytalan."},{"id":"D","text":"Reprezintă aproximativ 65% din totalul componentelor celulare desmodontale."},{"id":"E","text":"Au un fenotip identic cu cel al fibroblastelor gingivale."}],"correct":["A","B","D"],"pages":[294],"source":"set-2"},{"id":"set2-4GMkaiVj","fingerprint":"8ed598984baf6c8a","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce reprezintă fibrele Sharpey?","options":[{"id":"A","text":"Un tip de elastină imatură cu direcție paralelă cu rădăcina."},{"id":"B","text":"Fibre care apar de novo într-un parodonțiu regenerat."},{"id":"C","text":"Fibrele de colagen cu traseu ondulat situate strict în zona interstițială."},{"id":"D","text":"Componentele celulare majoritare ale ligamentului parodontal."},{"id":"E","text":"Porțiunile terminale ale fibrelor principale inserate în cement și în os."}],"correct":["E"],"pages":[294],"source":"set-2"},{"id":"set2-oqWAnkXG","fingerprint":"27832c70e2e87a7e","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect fibrele de oxytalan?","options":[{"id":"A","text":"Reprezintă principalul component fibros al ligamentului parodontal."},{"id":"B","text":"Sunt porțiuni terminale calcificate ale fibrelor ligamentare principale."},{"id":"C","text":"Sunt un tip de elastină imatură care pot apărea de novo în parodonțiul regenerat."},{"id":"D","text":"Sunt situate în apropierea vaselor sanguine și se crede că participă la controlul fluxului sanguin."},{"id":"E","text":"Se inseră în cement în treimea cervicală a rădăcinii."}],"correct":["C","D"],"pages":[294],"source":"set-2"},{"id":"set2-4bqgxESt","fingerprint":"82300893148bdfe4","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Un pacient se prezintă cu un dinte care nu are antagonist de mai mulți ani și, prin urmare, nu este în funcție. Ce modificare a ligamentului parodontal este de așteptat să fie observată pe o radiografie?","options":[{"id":"A","text":"O creștere a lățimii spațiului ligamentar din cauza lipsei de stimulare."},{"id":"B","text":"Apariția unei radioopacități în locul radiotransparenței caracteristice."},{"id":"C","text":"Lățimea spațiului ligamentar va rămâne neschimbată, având o medie constantă de 0,2 mm."},{"id":"D","text":"O diminuare a lățimii spațiului ligamentar."},{"id":"E","text":"O lărgire a spațiului în regiunea mijlocie a rădăcinii."}],"correct":["D"],"pages":[294],"source":"set-2"},{"id":"set2-ygGDLMjq","fingerprint":"01fbde7ed5ac1e04","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care sunt componentele principale ale substanței fundamentale din desmodonțiu?","options":[{"id":"A","text":"Resturile epiteliale Malassez și celule mezenchimale nediferențiate."},{"id":"B","text":"Glicozaminoglicani și glicoproteine."},{"id":"C","text":"Vase sanguine și nervi."},{"id":"D","text":"Fibre de colagen și fibre de oxytalan."},{"id":"E","text":"Fibroblaste și osteoblaste."}],"correct":["B"],"pages":[294],"source":"set-2"},{"id":"set2-zIdN162n","fingerprint":"2a22f8382710b056","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este originea nervilor din parodonțiu care înregistrează durerea, atingerea și presiunea și unde este localizat centrul lor trofic?","options":[{"id":"A","text":"Provin din nervul facial, cu centrul trofic în ganglionul geniculat."},{"id":"B","text":"Provin din ramuri ale nervului facial, cu centrul trofic în ganglionul semilunar."},{"id":"C","text":"Provin din nervul trigeminal, cu centrul trofic în ganglionul semilunar."},{"id":"D","text":"Provin din nervul glosofaringian, cu centrul trofic în ganglionul otic."},{"id":"E","text":"Provin din nervul trigeminal, cu centrul trofic în ganglionul geniculat."}],"correct":["C"],"pages":[295],"source":"set-2"},{"id":"set2-1UKJFxh7","fingerprint":"b1dffbd5d92be786","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele reprezintă funcții fizice ale ligamentului parodontal?","options":[{"id":"A","text":"Asigurarea nutriției cementului, a osului alveolar și a gingiei."},{"id":"B","text":"Atașarea dintelui de osul alveolar și protejarea vaselor și nervilor de leziuni mecanice."},{"id":"C","text":"Transmiterea senzațiilor dureroase, tactile și de presiune."},{"id":"D","text":"Participarea la formarea și resorbția osului alveolar și a cementului."},{"id":"E","text":"Menținerea relației corecte dintre țesuturile gingivale și dinte."}],"correct":["B","E"],"pages":[295],"source":"set-2"},{"id":"set2-gghehsaW","fingerprint":"b9fd39a8152f469f","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce caracteristică diferențiază fundamental cementul radicular de țesutul osos?","options":[{"id":"A","text":"Cementul conține fibre de colagen încorporate într-o matrice organică."},{"id":"B","text":"Cementul nu suferă resorbție sau remodelare fiziologică."},{"id":"C","text":"Cementul este un țesut mezenchimal mineralizat."},{"id":"D","text":"Cementul permite inserția fibrelor desmodontale principale."},{"id":"E","text":"Cementul este de culoare gălbuie și mai mat decât smalțul."}],"correct":["B"],"pages":[295],"source":"set-2"},{"id":"set2-WW-yIOwM","fingerprint":"3d6004b156f81a5a","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este cea mai frecventă relație anatomică între cement și smalț la nivelul joncțiunii smalț-cement?","options":[{"id":"A","text":"Relația este variabilă și nu există un tipar predominant."},{"id":"B","text":"Smalțul acoperă cementul pe o porțiune mică."},{"id":"C","text":"Există un spațiu între cement și smalț, lăsând dentina expusă."},{"id":"D","text":"Cementul și smalțul sunt în contact cap la cap."},{"id":"E","text":"Cementul acoperă smalțul."}],"correct":["E"],"pages":[295],"source":"set-2"},{"id":"set2-QKNNe7Yy","fingerprint":"87b53a9879e45d8a","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Referitor la grosimea cementului radicular, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Grosimea este mai mare pe suprafețele meziale decât pe cele distale."},{"id":"B","text":"Pe suprafețele distale, grosimea cementului este mai mare."},{"id":"C","text":"În treimea coronară a rădăcinii, grosimea variază între 150 și 200 µm."},{"id":"D","text":"Cementul este cel mai gros în treimea apicală și în zonele de furcație radiculară."},{"id":"E","text":"Grosimea cementului este uniformă pe toată suprafața radiculară."}],"correct":["B","D"],"pages":[295],"source":"set-2"},{"id":"set2-SKtI2UJF","fingerprint":"29c83fc1cd299100","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Din ce surse provin fibrele de colagen de la nivelul cementului radicular și ce celule le produc?","options":[{"id":"A","text":"Fibrele extrinseci sunt produse de cementoblaști, iar cele intrinseci de fibroblaști."},{"id":"B","text":"Toate fibrele sunt intrinseci și sunt produse de cementoblaști."},{"id":"C","text":"Fibrele extrinseci sunt produse de fibroblaști, iar cele intrinseci aparțin matricii cementare și sunt produse de cementoblaști."},{"id":"D","text":"Fibrele intrinseci sunt produse de osteoblaști, iar cele extrinseci de cementoblaști."},{"id":"E","text":"Toate fibrele sunt extrinseci (fibre Sharpey) și sunt produse de fibroblaști."}],"correct":["C"],"pages":[295],"source":"set-2"},{"id":"set2-icbQsOgM","fingerprint":"373781d9f1bc0313","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt afirmațiile corecte cu privire la originea fibrelor de colagen din cementul radicular?","options":[{"id":"A","text":"Fibrele extrinseci reprezintă porțiunea terminală a fibrelor principale ale ligamentului parodontal și sunt produse de fibroblaști."},{"id":"B","text":"Fibrele extrinseci, denumite și fibre Sharpey, sunt produse de cementoblaști."},{"id":"C","text":"Atât fibrele intrinseci, cât și cele extrinseci sunt produse exclusiv de cementoblaști."},{"id":"D","text":"Fibrele intrinseci sunt produse de fibroblaști și aparțin matricii cementare."},{"id":"E","text":"Fibrele intrinseci sunt produse de cementoblaști și aparțin matricii cementare."}],"correct":["A","E"],"pages":[296],"source":"set-2"},{"id":"set2-UXzxZV7y","fingerprint":"67e69127d4bc3e3e","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce caracteristici definitorii are cementul acelular, cunoscut și ca AEFC (acellular extrinsic fibre cementum)?","options":[{"id":"A","text":"Este mai slab mineralizat decât cementul secundar."},{"id":"B","text":"Conține numeroase cementocite localizate în lacune."},{"id":"C","text":"Nu conține celule și are ca structură principală fibrele extrinseci."},{"id":"D","text":"Acoperă treimea apicală a rădăcinii și zonele de furcație."},{"id":"E","text":"Se formează după ce dintele a atins planul de ocluzie."}],"correct":["C"],"pages":[296],"source":"set-2"},{"id":"set2-2dN4_Mh5","fingerprint":"eb4f0a4b0520cbe8","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt particularitățile cementului celular, denumit și cement secundar sau CIFC (cellular intrinsic fibre cementum)?","options":[{"id":"A","text":"Este localizat în treimea apicală a rădăcinii și în zonele de furcație."},{"id":"B","text":"Este primul tip de cement depus pe dentina radiculară în curs de formare."},{"id":"C","text":"Conține celule numite cementocite, care sunt localizate în lacune."},{"id":"D","text":"Este mai puternic mineralizat comparativ cu cementul primar."},{"id":"E","text":"Se formează după ce dintele atinge planul de ocluzie."}],"correct":["A","C","E"],"pages":[296],"source":"set-2"},{"id":"set2-wq-ncmlV","fingerprint":"e42cc94e123311a9","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este una dintre funcțiile cementului radicular legată de uzura ocluzală?","options":[{"id":"A","text":"Protejarea dentinei radiculare împotriva stimulilor termici."},{"id":"B","text":"Asigurarea suportului osos pentru dinții supuși forțelor ocluzale intense."},{"id":"C","text":"Repararea fracturilor radiculare prin depunerea de cement acelular."},{"id":"D","text":"Ancorarea fibrelor ligamentului parodontal în osul alveolar."},{"id":"E","text":"Compensarea erupției dintelui ca răspuns la atriție, prin formare continuă de cement."}],"correct":["E"],"pages":[296],"source":"set-2"},{"id":"set2-E_aJ8N7_","fingerprint":"a80e4c342dca4967","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce caracteristică fundamentală definește procesul alveolar?","options":[{"id":"A","text":"Morfologia sa este independentă de forma, mărimea și funcția dinților."},{"id":"B","text":"Este compus în principal din cement mixt stratificat."},{"id":"C","text":"Reprezintă osul bazal al maxilarelor, situat apical de rădăcinile dentare."},{"id":"D","text":"Este format exclusiv din os spongios cu rol de susținere."},{"id":"E","text":"Este o structură osoasă dentar-dependentă, care se dezvoltă odată cu erupția dinților și dispare după pierderea lor."}],"correct":["E"],"pages":[296],"source":"set-2"},{"id":"set2-dHzpKN8s","fingerprint":"cf747c11accf57ad","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este localizarea normală a crestei alveolare în raport cu joncțiunea smalț-cement (JSC)?","options":[{"id":"A","text":"La o distanță variabilă, neinfluențată de poziția dintelui."},{"id":"B","text":"La aproximativ 1,5-2 mm coronar de joncțiunea smalț-cement."},{"id":"C","text":"La nivelul treimii apicale a rădăcinii dintelui."},{"id":"D","text":"La aproximativ 1,5-2 mm apical de joncțiunea smalț-cement."},{"id":"E","text":"La un nivel identic cu joncțiunea smalț-cement."}],"correct":["D"],"pages":[296],"source":"set-2"},{"id":"set2-gyc5xIEh","fingerprint":"7fb266e75cdd1fd5","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Ce denumiri alternative primește corticala internă a osului alveolar și care sunt justificările acestora?","options":[{"id":"A","text":"Se numește lamina dura datorită aspectului său histologic cu multiple orificii."},{"id":"B","text":"Se numește os trabecular datorită dispunerii septurilor sale interne."},{"id":"C","text":"Se numește lamina dura datorită aspectului său radiologic de bandă liniară cu radioopacitate crescută."},{"id":"D","text":"Se numește lamina cribriforma datorită aspectului său radiologic de bandă cu radioopacitate crescută."},{"id":"E","text":"Se numește lamina cribriforma datorită aspectului histologic cu orificii prin care trec pachetele vasculo-nervoase."}],"correct":["C","E"],"pages":[296],"source":"set-2"},{"id":"set2-lV1Rb5JH","fingerprint":"0143b20c031b3a0d","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care sunt componentele osului alveolar?","options":[{"id":"A","text":"Corticala externă, corticala internă și osul spongios."},{"id":"B","text":"Corticala externă, osul bazal și septurile interradiculare."},{"id":"C","text":"Os haversian, os lamelar compact și os trabecular."},{"id":"D","text":"Cementul primar, cementul secundar și osul bazal."},{"id":"E","text":"Lamina dura, lamina cribriforma și septurile interdentare."}],"correct":["A"],"pages":[296],"source":"set-2"},{"id":"set2-j7fj9GH9","fingerprint":"28960a05aacc64b0","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este compoziția procentuală a componentelor extracelulare ale osului alveolar?","options":[{"id":"A","text":"Aproximativ 60% substanță anorganică, 25% material organic și 15% apă."},{"id":"B","text":"Aproximativ 25% substanță anorganică, 60% material organic și 15% apă."},{"id":"C","text":"Aproximativ 15% substanță anorganică, 25% material organic și 60% apă."},{"id":"D","text":"Aproximativ 90% substanță anorganică, 5% material organic și 5% apă."},{"id":"E","text":"Aproximativ 60% material organic, 25% substanță anorganică și 15% apă."}],"correct":["A"],"pages":[297],"source":"set-2"},{"id":"set2-GeWlO3mI","fingerprint":"5444c6cce43ee55e","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce componentă organică reprezintă 90% din matricea organică a osului alveolar și ce funcție îndeplinește?","options":[{"id":"A","text":"Osteocalcina, care inițiază procesul de mineralizare."},{"id":"B","text":"Glicoproteine, care asigură legătura dintre celule și matrice."},{"id":"C","text":"Hidroxiapatita, care oferă rigiditate și rezistență la compresiune."},{"id":"D","text":"Colagen de tip I, care oferă rezistență și flexibilitate."},{"id":"E","text":"Factori de creștere, care reglează activitatea celulară."}],"correct":["D"],"pages":[297],"source":"set-2"},{"id":"set2-UGerQgSv","fingerprint":"263a8cdfcce87594","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt funcțiile osteoblastelor în contextul osului alveolar?","options":[{"id":"A","text":"Secretă molecule care controlează propria lor activitate, precum citokine și prostaglandine."},{"id":"B","text":"Secretă molecule care influențează activarea osteoclastelor."},{"id":"C","text":"Secretă o matrice de os nemineralizată, denumită „osteoid”."},{"id":"D","text":"Sunt responsabile direct de procesul de resorbție osoasă."},{"id":"E","text":"Sunt celulele postmitotice cele mai numeroase din os."}],"correct":["A","B","C"],"pages":[297],"source":"set-2"},{"id":"set2-rwk2Csxt","fingerprint":"d0fa83788862b762","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care afirmație descrie corect osteocitele?","options":[{"id":"A","text":"Sunt celule responsabile de resorbția osoasă."},{"id":"B","text":"Sunt celule postmitotice și reprezintă peste 90% din celulele osoase."},{"id":"C","text":"Impregnează și înconjoară fibrele de colagen pentru a oferi rigiditate."},{"id":"D","text":"Sunt celule precursoare care se diferențiază în osteoblaste și osteoclaste."},{"id":"E","text":"Secretă matricea de os nemineralizată, numită osteoid."}],"correct":["B"],"pages":[297],"source":"set-2"},{"id":"set2-ujOyqa04","fingerprint":"6b0aec2e35de3139","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele sunt funcții ale osului alveolar?","options":[{"id":"A","text":"Asigură mișcarea dinților prin fenomene de remodelare osoasă constantă."},{"id":"B","text":"Reprezintă suportul rigid al dintelui, oferindu-i stabilitate în timpul funcțiilor."},{"id":"C","text":"Oferă rezistență și flexibilitate prin conținutul său de colagen de tip I."},{"id":"D","text":"Fixează fibrele principale ale ligamentului parodontal pentru a susține dinții."},{"id":"E","text":"Secretă factori de creștere, osteocalcină și osteonectină."}],"correct":["A","B","D"],"pages":[297],"source":"set-2"},{"id":"set2-2bA2PuFL","fingerprint":"9118052f4706ddac","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Ce implică procesul de remodelare a osului alveolar care permite mișcarea dinților?","options":[{"id":"A","text":"Creșterea densității osoase prin depunerea exclusivă de os nou."},{"id":"B","text":"Mineralizarea osteoidului secretat de osteocite."},{"id":"C","text":"Resorbția și reformarea continuă a trabeculelor osoase."},{"id":"D","text":"Migrarea dinților în direcție mezială pentru a compensa atriția."},{"id":"E","text":"Dizolvarea masei osului cortical și înlocuirea acesteia cu os nou."}],"correct":["C","D","E"],"pages":[297],"source":"set-2"},{"id":"set2-Ryfd9N1B","fingerprint":"38d4820f4037c18f","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele țesuturi intră în alcătuirea parodonțiului profund?","options":[{"id":"A","text":"Smalțul dentar"},{"id":"B","text":"Osul alveolar"},{"id":"C","text":"Gingia"},{"id":"D","text":"Cementul radicular"},{"id":"E","text":"Ligamentul parodontal"}],"correct":["B","D","E"],"pages":[291],"source":"set-2"},{"id":"set2-hNMeMWJn","fingerprint":"c880b3b95d002495","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la funcțiile și caracteristicile componentelor aparatului de susținere a dintelui?","options":[{"id":"A","text":"Funcționarea parodonțiului rămâne la parametri optimi chiar și în cazul unor modificări izolate ale unei singure componente."},{"id":"B","text":"Desmodonțiul reprezintă ansamblul de structuri care conectează dintele de osul alveolar."},{"id":"C","text":"Ligamentul parodontal este considerat o componentă majoră a parodonțiului superficial."},{"id":"D","text":"Cementul radicular este țesutul care acoperă rădăcina dintelui și fixează fibrele ligamentului parodontal."},{"id":"E","text":"Gingia acoperă osul alveolar și constituie structura vizibilă la examinarea clinică a parodonțiului."}],"correct":["B","D","E"],"pages":[291],"source":"set-2"},{"id":"set2-JkeVDycL","fingerprint":"ad2992190bc08883","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele elemente anatomice au rolul direct de a fixa fibrele ligamentului parodontal?","options":[{"id":"A","text":"Cementul radicular"},{"id":"B","text":"Gingia"},{"id":"C","text":"Parodonțiul superficial"},{"id":"D","text":"Osul alveolar"},{"id":"E","text":"Desmodonțiul"}],"correct":["A","D"],"pages":[291],"source":"set-2"},{"id":"set2-Ylf0IY9k","fingerprint":"ca8459214d7c1156","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt caracteristicile anatomice și topografice ale gingiei atașate?","options":[{"id":"A","text":"Joncțiunea muco-gingivală este clar vizibilă ca linie de demarcație în zona palatului dur."},{"id":"B","text":"Reprezintă exact aceeași entitate anatomică și dimensională cu gingia keratinizată."},{"id":"C","text":"Este separată de mucoasa alveolară prin joncțiunea muco-gingivală."},{"id":"D","text":"Pe versantul vestibular, înălțimea sa este mai redusă la mandibulă comparativ cu maxilarul."},{"id":"E","text":"Modificările înălțimii sale pe parcursul vieții se datorează deplasării apicale continue a joncțiunii muco-gingivale."}],"correct":["C","D"],"pages":[292],"source":"set-2"},{"id":"set2-wrhRU9GE","fingerprint":"147d537a5e6db561","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Ce reprezintă colul gingival din punct de vedere anatomic?","options":[{"id":"A","text":"Porțiunea coronară a gingiei care înconjoară dinții asemenea unei colerete."},{"id":"B","text":"Cel mai apical punct al marginii gingiei libere situat pe fața vestibulară a dintelui."},{"id":"C","text":"Depresiunea care unește crestele de țesut vestibular și oral ale papilei interdentare în zonele laterale."},{"id":"D","text":"Linia de demarcație imperceptibilă situată între gingia atașată și mucoasa alveolară în zona palatului dur."},{"id":"E","text":"Spațiul în formă de „V” delimitat de suprafața dentară și epiteliul joncțional."}],"correct":["C"],"pages":[292],"source":"set-2"},{"id":"set2-Vws0jXzi","fingerprint":"87b5f0577c750d3a","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt trăsăturile caracteristice ale gingiei marginale?","options":[{"id":"A","text":"Este delimitată de gingia atașată prin șanțul gingiei libere, acesta fiind vizibil clinic la toți pacienții."},{"id":"B","text":"Punctul său situat cel mai apical la nivelul coroanei poartă denumirea de zenit gingival."},{"id":"C","text":"Prezintă o grosime de aproximativ 1 mm, cu variații individuale cuprinse între 0,5 și 2 mm."},{"id":"D","text":"Aderența bazei sale la smalț se realizează exclusiv prin intermediul laminei propria."},{"id":"E","text":"Constituie peretele extern al șanțului gingival."}],"correct":["B","C","E"],"pages":[291],"source":"set-2"},{"id":"set2-QRBC-lop","fingerprint":"9a8b8d0f35ab8b5b","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt afirmațiile valabile privind caracteristicile anatomice și dimensionale ale șanțului gingival?","options":[{"id":"A","text":"Este un spațiu sub formă de „V”, delimitat de suprafața dintelui și de epiteliul gingiei libere."},{"id":"B","text":"Adâncimea sa medie, determinată pe secțiuni histologice, are o valoare fixă de 1,5 mm."},{"id":"C","text":"Spațiul său găzduiește lichidul crevicular, a cărui analiză aduce informații utile în diagnosticul bolilor parodontale."},{"id":"D","text":"În condiții de sănătate parodontală, limitele de variație ale adâncimii histologice se situează între 0,5 și 3 mm."},{"id":"E","text":"Peretele său extern este format în exclusivitate de porțiunea coronară a gingiei atașate."}],"correct":["A","C","D"],"pages":[292],"source":"set-2"},{"id":"set2-xey-VL-v","fingerprint":"0dfc824edb15b556","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt factorii anatomici și topografici ce determină arhitectura și forma papilei interdentare?","options":[{"id":"A","text":"Existența la nivel clinic a recesiunilor gingivale."},{"id":"B","text":"Distanța existentă între punctul de contact și creasta osoasă subiacentă."},{"id":"C","text":"Existența punctului de contact interproximal."},{"id":"D","text":"Adâncimea șanțului gingiei libere de pe versanții vestibulari adiacenți."},{"id":"E","text":"Extinderea coronară a joncțiunii muco-gingivale în funcție de fenotipul parodontal."}],"correct":["A","B","C"],"pages":[292],"source":"set-2"},{"id":"set2-ppinwYyN","fingerprint":"f1d92f240c1cb943","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt elementele de vulnerabilitate histologică ale epiteliului joncțional?","options":[{"id":"A","text":"Spațiile intercelulare înguste care reduc permeabilitatea."},{"id":"B","text":"Contactul plan dintre epiteliu și lamina propria."},{"id":"C","text":"Numărul crescut de desmozomi comparativ cu epiteliul gingival extern."},{"id":"D","text":"Rezistența redusă la detașare."},{"id":"E","text":"Prezența unui strat cornos bine reprezentat la interfața cu mediul oral."}],"correct":["B","D"],"pages":[292,293,294],"source":"set-2"},{"id":"set2-1R1R6q4E","fingerprint":"e08df5a95df2a645","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care grup de fibre conjunctive gingivale are originea la nivelul cementului unui dinte și se inseră pe cementul dintelui adiacent, având o traiectorie mezio-distală deasupra septului interdentar?","options":[{"id":"A","text":"Fibrele dento-periostale"},{"id":"B","text":"Fibrele dento-gingivale"},{"id":"C","text":"Fibrele alveolo-gingivale"},{"id":"D","text":"Fibrele circulare"},{"id":"E","text":"Fibrele transseptale"}],"correct":["E"],"pages":[292,293,294],"source":"set-2"},{"id":"set2-0FGC36ZX","fingerprint":"d2366981fc90def4","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la structura și caracteristicile epiteliului gingival extern?","options":[{"id":"A","text":"Acoperă exclusiv suprafața interioară a șanțului gingival."},{"id":"B","text":"Limita dintre acesta și țesutul conjunctiv subiacent are un traiect strict rectiliniu."},{"id":"C","text":"Prezintă o grosime de aproximativ 0,2-0,3 mm."},{"id":"D","text":"Este un epiteliu pavimentos pluristratificat, keratinizat."},{"id":"E","text":"Partea mediană a papilei interdentare reprezintă un element de vulnerabilitate histologică."}],"correct":["C","D","E"],"pages":[292,293,294],"source":"set-2"},{"id":"set2-3kT9bosL","fingerprint":"26d4c75f2ccea3cc","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt afirmațiile adevărate privind componentele structurale și celulare ale laminei propria gingivale?","options":[{"id":"A","text":"În condiții de sănătate parodontală, fibroblastele sintetizează colagen, dar nu îl pot degrada."},{"id":"B","text":"Fibrele de colagen reprezintă aproximativ 60% din volumul țesutului conjunctiv gingival."},{"id":"C","text":"Substanța fundamentală conține în principal glicoproteine și polizaharide."},{"id":"D","text":"Fibroblastele reprezintă aproximativ 35% din volumul total al laminei propria."},{"id":"E","text":"Stratul reticular se extinde profund, până la periostul osului alveolar."}],"correct":["B","C","E"],"pages":[292,293,294],"source":"set-2"},{"id":"set2-_GVtkDKO","fingerprint":"ec149813cc99a861","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Cum variază grosimea epiteliului joncțional în secțiune transversală?","options":[{"id":"A","text":"Prezintă o grosime uniformă de 10-20 de straturi celulare pe toată întinderea sa."},{"id":"B","text":"Este alcătuit exclusiv din 1-3 straturi de celule la nivelul porțiunii coronare."},{"id":"C","text":"Este mai gros spre sulcus și se îngustează progresiv spre profunzime."},{"id":"D","text":"Este mai subțire spre sulcus și se îngroașă progresiv la nivel apical."},{"id":"E","text":"Prezintă un strat cornos gros de 10-20 de rânduri de celule spre sulcus."}],"correct":["C"],"pages":[292,293,294],"source":"set-2"},{"id":"set2-o1aT8Atd","fingerprint":"8e695cf491e9b7ca","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care dintre afirmațiile referitoare la caracteristicile macroscopice ale spațiului ligamentului parodontal este precisă?","options":[{"id":"A","text":"Lățimea ligamentului parodontal atinge valoarea maximă în regiunea mijlocie a rădăcinii dentare."},{"id":"B","text":"Legătura structurală realizată de ligament se stabilește între dentina radiculară și peretele extern al osului alveolar."},{"id":"C","text":"Spațiul ligamentului parodontal este detectat radiografic ca o radiotransparență cu o lățime medie de 0,2 mm, mai largă în regiunile apicale și gingivale."},{"id":"D","text":"Dimensiunea spațiului ligamentului parodontal crește în jurul dinților neerupți și scade în cazul dinților supuși hiperfuncției."},{"id":"E","text":"Ligamentul parodontal este identificat pe radiografii sub forma unei benzi radioopace care urmărește conturul rădăcinii."}],"correct":["C"],"pages":[294,295],"source":"set-2"},{"id":"set2-qda3VixO","fingerprint":"973cf782d97acd07","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele aspecte descriu caracteristicile structurale și funcționale ale fibroblastelor din ligamentul parodontal?","options":[{"id":"A","text":"Fenotipul lor este identic cu cel al fibroblastelor prezente în țesutul gingival adiacent."},{"id":"B","text":"Rolul lor principal constă în sinteza substanței fundamentale și a variatelor tipuri de fibre desmodontale."},{"id":"C","text":"Implicarea lor se limitează strict la sinteza fibrelor de colagen, degradarea acestora fiind asigurată exclusiv de osteoclaste."},{"id":"D","text":"Dețin capacitatea de a fagocita și degrada fibrele de colagen prin acțiunea enzimelor hidrolitice."},{"id":"E","text":"Reprezintă principala componentă celulară a ligamentului, însumând 65% din totalul elementelor celulare desmodontale."}],"correct":["B","D","E"],"pages":[294,295],"source":"set-2"},{"id":"set2-XgyT3Yr9","fingerprint":"985da2b79952a34e","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Ce caracteristici de ordin topografic și fiziologic definesc fibrele de oxytalan de la nivelul parodonțiului?","options":[{"id":"A","text":"Au particularitatea de a putea apărea de novo la nivelul unui parodonțiu regenerat."},{"id":"B","text":"Sunt constituite dintr-un tip de elastină imatură și prezintă o direcție paralelă cu rădăcina dentară."},{"id":"C","text":"Dispunerea lor topografică în apropierea vaselor sanguine sugerează participarea la controlul fluxului sanguin."},{"id":"D","text":"Apar exclusiv în cursul proceselor de dezvoltare embrionară, neputând fi generate într-un parodonțiu regenerat."},{"id":"E","text":"Se inseră la nivelul cementului dentar, fiind dispuse cu predilecție în treimea cervicală a rădăcinii."}],"correct":["A","B","C"],"pages":[294,295],"source":"set-2"},{"id":"set2-Up-V_jYJ","fingerprint":"4f5dd537eb72c2b8","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele elemente intră în alcătuirea substanței fundamentale și a zonei interstițiale din structura ligamentului parodontal?","options":[{"id":"A","text":"Fibronectina și laminina sunt clasificate drept glicozaminoglicani ce abundă la nivelul substanței fundamentale."},{"id":"B","text":"Substanța fundamentală ocupă spațiile dintre fibre și celule, având drept componente principale glicozaminoglicanii și glicoproteinele."},{"id":"C","text":"Vasele sanguine interstițiale au un traseu apico-coronar și tind să se grupeze între fibrele principale de colagen."},{"id":"D","text":"Acidul hialuronic și proteoglicanii se încadrează în categoria glicozaminoglicanilor prezenți în substanța fundamentală desmodontală."},{"id":"E","text":"Zona interstițială a ligamentului parodontal conține exclusiv rețele de colagen și osteoblaste migratoare."}],"correct":["B","C","D"],"pages":[294,295],"source":"set-2"},{"id":"set2-vZ1lwdup","fingerprint":"c4a4e1c6f0257216","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele elemente se regăsesc printre rolurile funcționale specifice îndeplinite de ligamentul parodontal?","options":[{"id":"A","text":"Transmiterea senzațiilor dureroase, tactile și de presiune prelucrate prin intermediul tracturilor nervului trigemen."},{"id":"B","text":"Amortizarea șocurilor și asigurarea rezistenței la impactul forțelor ocluzale prin intermediul funcțiilor sale fizice."},{"id":"C","text":"Participarea celulelor ligamentului la formarea și resorbția osului alveolar pe parcursul mișcărilor fiziologice ale dinților."},{"id":"D","text":"Protecția structurilor neuro-vasculare împotriva leziunilor mecanice, acționând ca un înveliș de țesut moale."},{"id":"E","text":"Asigurarea nutriției smalțului și a dentinei coronare prin intermediul plexurilor vasculare bogate de la nivel desmodontal."}],"correct":["A","B","C","D"],"pages":[294,295],"source":"set-2"},{"id":"set2-Bu-sWJsv","fingerprint":"038b947bebceb7e3","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care sunt caracteristicile descriptive ale cementului acelular (primar)?","options":[{"id":"A","text":"Conține celule de tipul cementocitelor, dispuse la nivelul unor lacune specifice."},{"id":"B","text":"Prezintă un grad de mineralizare evident mai redus comparativ cu cementul celular."},{"id":"C","text":"Fibrele extrinseci reprezintă structura principală a acestui tip de cement, având un rol esențial în atașamentul dintelui."},{"id":"D","text":"Este sintetizat și depus abia după ce dintele atinge planul de ocluzie."},{"id":"E","text":"Reprezintă primul cement depus pe dentina rădăcinii în formare și acoperă cele 2/3 coronare ale dintelui."}],"correct":["C","E"],"pages":[295,296],"source":"set-2"},{"id":"set2-U2vD0SsL","fingerprint":"bc2f7f88f858e367","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care dintre următoarele afirmații descrie particularitățile fiziologice și macroscopice ale cementului radicular?","options":[{"id":"A","text":"Este un țesut bine inervat la nivelul joncțiunii smalț-cement, reflectând sensibilitatea cervicală."},{"id":"B","text":"Funcția sa esențială este reprezentată de susținerea vascularizației specifice ligamentului parodontal."},{"id":"C","text":"Are o consistență mai moale, un aspect mai mat în comparație cu smalțul și prezintă o culoare gălbuie."},{"id":"D","text":"Grosimea stratului de cement este mai redusă pe suprafețele distale comparativ cu cele meziale."},{"id":"E","text":"Suferă un proces constant de remodelare și resorbție fiziologică pentru adaptarea la solicitările ocluzale."}],"correct":["C"],"pages":[295,296],"source":"set-2"},{"id":"set2-psPudIbh","fingerprint":"188ec4fe702a3b83","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Ce detalii topografice și dimensionale referitoare la joncțiunile cementului sunt adevărate?","options":[{"id":"A","text":"La nivelul joncțiunii smalț-cement, cementul acoperă smalțul într-o proporție de 60% până la 65% din cazuri."},{"id":"B","text":"Situația în care cementul și smalțul nu sunt în contact se raportează în 30% din cazuri."},{"id":"C","text":"Joncțiunea cemento-dentinară se găsește la nivelul apexului, fiind locul de fuziune a cementului cu dentina pe fața internă a canalului radicular."},{"id":"D","text":"În cursul tratamentului endodontic, materialul de obturație radiculară trebuie să fie extins dincolo de joncțiunea cemento-dentinară."},{"id":"E","text":"Într-un procent de 5% până la 10% din cazuri, relația descrisă este un contact cap la cap între smalț și cement."}],"correct":["A","C"],"pages":[295,296],"source":"set-2"},{"id":"set2-j_FKHGJA","fingerprint":"3e49d0f4f745f5d2","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este originea și natura fibrelor extrinseci Sharpey situate la nivelul cementului radicular?","options":[{"id":"A","text":"Sunt sintetizate de către fibroblaști și constituie porțiunea terminală a fibrelor principale ale ligamentului parodontal."},{"id":"B","text":"Sunt formate din depuneri avasculare minerale continue aflate pe peretele intern al canalului radicular."},{"id":"C","text":"Reprezintă structuri aparținând exclusiv matricei cementare, fiind produse direct de cementoblaști."},{"id":"D","text":"Aceste fibre se formează prin alternanța depunerii de cement acelular și celular la nivelul furcațiilor."},{"id":"E","text":"Reprezintă structura de bază exclusivă a cementului secundar, având rol de reparație la nivel apical."}],"correct":["A"],"pages":[295,296],"source":"set-2"},{"id":"set2-KwrhV3-s","fingerprint":"a874e4ced9408ab7","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Ce particularități privind grosimea și rolurile funcționale descriu corect cementul radicular?","options":[{"id":"A","text":"În regiunea apicală, procesul de formare continuă a cementului are un ritm mult mai lent comparativ cu zona cervicală."},{"id":"B","text":"În treimea coronară a rădăcinii, grosimea cementului este de 16 până la 60 µm, o valoare comparabilă cu grosimea unui fir de păr."},{"id":"C","text":"Activitatea de depunere a cementului radicular este stopată fiziologic în momentul în care dintele atinge planul de ocluzie."},{"id":"D","text":"Grosimea sa prezintă valorile cele mai mari, cuprinse între 150 și 200 µm, la nivelul treimii apicale și în zonele de furcație."},{"id":"E","text":"Erupția compensatoare a dintelui ca răspuns la atriție este facilitată de formarea continuă de cement."}],"correct":["B","D","E"],"pages":[295,296],"source":"set-2"},{"id":"set2-Ax_-K1PX","fingerprint":"0e3191ea463f043e","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele afirmații descriu aspectele macroscopice și organizarea structurală a osului alveolar?","options":[{"id":"A","text":"Osul bazal reprezintă acea porțiune a procesului alveolar care este dependentă de prezența dinților și susține alveolele dentare."},{"id":"B","text":"Osul spongios este situat între corticala externă și cea internă, jalonând traiectul funcțional al fibrelor Sharpey."},{"id":"C","text":"Corticala internă este structura formată în principal din os haversian și os lamelar compact."},{"id":"D","text":"Lamina cribriforma reprezintă denumirea corticalei interne justificată de prezența orificiilor destinate trecerii pachetelor vasculo-nervoase."},{"id":"E","text":"Osul alveolar înconjoară dintele până la aproximativ 1,5-2 mm apical de joncțiunea smalț-cement."}],"correct":["B","D","E"],"pages":[297],"source":"set-2"},{"id":"set2-ZTqbGWgm","fingerprint":"d8ff966ec07f9b0d","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este proporția și natura componentelor structurale ale osului alveolar?","options":[{"id":"A","text":"Componenta organică constituie 25% din țesutul conjunctiv extracelular, având în structură preponderent colagen de tip I."},{"id":"B","text":"Apa reprezintă 60% din compoziția componentelor extracelulare ale osului alveolar."},{"id":"C","text":"Substanța anorganică reprezintă aproximativ 90% din componentele extracelulare, fiind constituită din hidroxiapatită."},{"id":"D","text":"Substanța organică include un amestec complex de proteine în proporție de 90%, printre care osteocalcină și osteonectină."},{"id":"E","text":"Osteocitele reprezintă sub 10% din totalul celulelor osoase, fiind celule cu activitate mitotică intensă."}],"correct":["A"],"pages":[297],"source":"set-2"},{"id":"set2-GuyJDmhH","fingerprint":"a35c38751c380c1c","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Care dintre următoarele caracteristici sunt specifice activității celulare și funcțiilor osului alveolar?","options":[{"id":"A","text":"Fenomenele de remodelare osoasă permit migrarea fiziologică a dinților în direcție mezială pentru compensarea atriției."},{"id":"B","text":"Osteocitele alcătuiesc cel mai numeros tip celular din osul propriu-zis."},{"id":"C","text":"Osteoblastele secretă molecule care controlează propria activitate (factori de creștere, citokine și prostaglandine) și molecule care influențează activarea osteoclastelor."},{"id":"D","text":"Procesul alveolar reprezintă o structură osoasă care se dezvoltă independent de mecanismul de erupție dentară."},{"id":"E","text":"Osteoblastele secretă osteoidul, o matrice osoasă deja mineralizată în momentul sintezei."}],"correct":["A","B","C"],"pages":[297],"source":"set-2"},{"id":"set2-iQzC0fLp","fingerprint":"73a03408875515ca","chapterId":"set-2","subchapterId":"set2-4.01","type":"CM","text":"Ce particularități prezintă peretele intern al alveolei dentare?","options":[{"id":"A","text":"Este vizibil radiologic sub forma unei benzi lineare caracterizate de o radioopacitate scăzută."},{"id":"B","text":"Acționează ca o barieră complet lipsită de perforații între cementul radicular și osul spongios."},{"id":"C","text":"Găzduiește traiectul pachetelor vasculo-nervoase din ligamentul parodontal prin orificii specifice laminei cribriforma."},{"id":"D","text":"Dispune de septuri sub forma unor trabecule osoase care separă spațiile intraosoase."},{"id":"E","text":"Este format de corticala internă a osului alveolar."}],"correct":["C","E"],"pages":[297],"source":"set-2"},{"id":"set2-yzH7RtA3","fingerprint":"0ef3d1e910037ec3","chapterId":"set-2","subchapterId":"set2-4.01","type":"CS","text":"Care este mecanismul prin care osul alveolar asigură mișcarea dinților pe parcursul vieții?","options":[{"id":"A","text":"Scăderea concentrației de hidroxiapatită la 15% pentru a conferi flexibilitate peretelui intern al alveolei."},{"id":"B","text":"Atrage dispariția imediată a laminei dura în zonele interradiculare sub acțiunea forțelor ocluzale distale."},{"id":"C","text":"Dizolvarea masei de os cortical și înlocuirea cu os nou, concomitent cu resorbția și reformarea continuă a trabeculelor osoase."},{"id":"D","text":"Transformarea osteocitelor medulare în osteoblaste active capabile să secrete colagen de tip I la suprafața radiculară."},{"id":"E","text":"Apoziția exclusivă de os haversian la nivelul corticalei externe, fără implicarea structurilor trabeculare medulare."}],"correct":["C"],"pages":[297],"source":"set-2"}];
